"use server";

import { revalidatePath } from "next/cache";

// In a real application, this would be stored in a database
// Using a simple in-memory store for demonstration
let notificationPreference: Record<string, boolean> = {};

export async function getNotificationPreference(userId: string): Promise<boolean> {
  // Default to true (notifications enabled) if not set
  return notificationPreference[userId] ?? true;
}

export async function toggleNotificationPreference(userId: string): Promise<boolean> {
  // Get current preference (default to true if not set)
  const currentPreference = notificationPreference[userId] ?? true;

  // Toggle the preference
  const newPreference = !currentPreference;
  notificationPreference[userId] = newPreference;

  // Refresh the current page to show updated preference
  // This is Next.js's recommended approach for refreshing the current page
  // from within a Server Action without redirecting
  revalidatePath("/");

  return newPreference;
}

