import NotificationToggle from "./components/NotificationToggle";
import { getNotificationPreference } from "./actions/notification-actions";

// In a real app, this would come from authentication
const DEMO_USER_ID = "user-123";

export default async function Home() {
  // Fetch the current notification preference on the server
  const notificationsEnabled = await getNotificationPreference(DEMO_USER_ID);

  return (
    <main style={{ padding: "24px" }}>
      <h1>Settings</h1>
      <section style={{ marginTop: "24px" }}>
        <h2>Notification Preferences</h2>
        <NotificationToggle
          userId={DEMO_USER_ID}
          initialEnabled={notificationsEnabled}
        />
        <p style={{ marginTop: "12px", color: "#666" }}>
          Current status: Notifications are{" "}
          <strong>{notificationsEnabled ? "enabled" : "disabled"}</strong>
        </p>
      </section>
    </main>
  );
}

